#[test]
fn local_access_timestamp_is_not_modification_timestamp() {
    let mut cursor = Cursor::new(include_bytes!("../fixtures/access-time-only.zip"));
    let file = zip::read::read_zipfile_from_stream(&mut cursor).unwrap().unwrap();
    let ts = file.extra_data_fields().find_map(|x| match x { ExtraField::ExtendedTimestamp(x) => Some(x), _=>None }).unwrap();
    assert_eq!((ts.mod_time(), ts.ac_time(), ts.cr_time()), (None, Some(123456789), None));
}
#[test]
fn writer_compression_matrix_roundtrip() {
    let methods = [CompressionMethod::Stored, CompressionMethod::Deflated, CompressionMethod::Bzip2, CompressionMethod::Zstd, CompressionMethod::Xz, CompressionMethod::Ppmd];
    for method in methods {
        for bytes in [b"".as_slice(), b"hello", "héllo, 世界".as_bytes()] {
            for large in [false,true] {
                let mut w = ZipWriter::new(Cursor::new(Vec::new()));
                w.start_file("file", SimpleFileOptions::default().compression_method(method).large_file(large)).unwrap();
                w.write_all(bytes).unwrap();
                let mut a = ZipArchive::new(w.finish().unwrap()).unwrap();
                let mut f = a.by_index(0).unwrap();
                assert_eq!(f.size(), bytes.len() as u64, "{method:?}, large={large}");
                let mut got=Vec::new(); f.read_to_end(&mut got).unwrap();
                assert_eq!(got,bytes, "{method:?}, large={large}");
            }
        }
    }
}
